export function quoins(g) {
  for (const { c: [cx, cz], n } of QUOINS) {
    for (let y = 1; y <= 9; y++) g.set(cx, y, cz, TRIM);
    for (const [nx, nz, f] of n) {
      for (let y = 1; y <= 9; y++) {
        if (y === 5 || y === 9) continue;
        if (f === "north" && y <= 4) continue;
        g.set(nx, y, nz, y % 2 === 0 ? TRIM : SIDING);
      }
    }
  }
}

